__NUXT_JSONP__("/anticorrupcion/noticias/corrupcion_e_ineficacia_en_insabi_segalmex_e_indep_marcan_el_sexenio_de_amlo", (function(a,b,c,d,e,f,g){return {data:[{post:{slug:"corrupcion_e_ineficacia_en_insabi_segalmex_e_indep_marcan_el_sexenio_de_amlo",title:"Corrupción e ineficacia en Insabi, Segalmex e Indep marcan el sexenio de AMLO",date:"2024-09-23T20:07:53.128Z",img:"https:\u002F\u002Fucarecdn.com\u002F6b671bb1-c337-45b4-a10a-d522000b7bb5\u002F","img-alt":"Insabi, Segalmex e Indep",autor:"Dulce Soto, Expansión",link:"https:\u002F\u002Fpolitica.expansion.mx\u002Fmexico\u002F2024\u002F09\u002F23\u002Fcorrupcion-en-insabi-segalmex-indep-marca-sexenio-amlo",category:"anticorrupcion",extracto:"En la administración que termina, el Insabi, Segalmex e Indep fueron señalados por su ineficacia o corrupción; sus fallas seguirán siendo un reto para Claudia Sheinbaum.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Tres instituciones que se crearon durante el sexenio de Andrés Manuel López Obrador para trabajar por la población más vulnerable, "},{type:b,tag:e,props:{},children:[{type:a,value:"operaron con corrupción, incompetencia y hasta \"amiguismo\""}]},{type:a,value:". Se trata del Instituto de Salud para el Bienestar ("},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:"), la paraestatal Seguridad Alimentaria Mexicana ("},{type:b,tag:e,props:{},children:[{type:a,value:"Segalmex"}]},{type:a,value:") y el Instituto para Devolver al Pueblo lo Robado ("},{type:b,tag:e,props:{},children:[{type:a,value:"Indep"}]},{type:a,value:")."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Las dependencias nacieron para llevar salud y alimentos a los más pobres, además de conseguir recursos para causas sociales con la venta de bienes incautados, pero lejos de cumplir con sus objetivos, se convirtieron en un dolor de cabeza para el Gobierno federal."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Aunque han desaparecido o se fusionarán, las fallas de estas dependencias causaron estragos tan profundos que sus efectos alcanzarán el sexenio de Claudia Sheinbaum, quien enfrentará retos importantes para consolidar lo que no lograron: garantizar salud, alimentación y prevenir la corrupción."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Especialistas consultados consideran que la gestión en estos tres organismos es resultado de una administración de “mucho discurso y pocas acciones concretas y factibles”, como menciona Emiliano Montes de Oca, coordinador anticorrupción en Ethos, Innovación en Políticas Públicas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"Segalmex, el mayor caso de corrupción"}]},{type:a,value:"\r\nEl desvío de recursos en Segalmex es el caso de corrupción más grande en este Gobierno. El propio López Obrador reconoció que es una “mancha” que se llevará de su sexenio."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Una de las cosas que más lamento fue el fraude en Segalmex, porque era una nueva dependencia para apoyar a los productores del campo, muy parecida a Conasupo de los viejos tiempos. Por descuido o mala suerte se corrompen funcionarios y lo lamenté mucho. Claro, están en la cárcel los responsables y no hay impunidad. Yo diría que esa es la mancha que me llevo”, afirmó el pasado 25 de julio en su conferencia matutina."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El Gobierno federal reconoce que el monto desfalcado es de sólo 2,700 millones de pesos, el 28% de los 9,500 mdp que documentó la Auditoría Superior de la Federación (ASF). De acuerdo con el titular de la Secretaría de la Función Pública, Roberto Salcedo, 4,700 mdp ya fueron aclarados, mientras que 2,100 mdp están en proceso de análisis para acreditación y en caso de no aclararse, constituirán un daño al erario, por lo que se presentarían las denuncias correspondientes."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sin embargo, investigaciones periodísticas apuntan a que el desfalco alcanzaría hasta los 12,000 o 15,000 millones de pesos, cifra que duplica la de la Estafa Maestra, el mayor caso de corrupción durante el sexenio de Enrique Peña Nieto, y 65 veces más que el daño por la Estela de Luz, que se dio en la administración del presidente Felipe Calderón."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Segalmex se creó para llevar alimentos básicos a las comunidades más pobres. En 2018, López Obrador, entonces presidente electo de México, anunció que "},{type:b,tag:e,props:{},children:[{type:a,value:"fusionaría las empresas Diconsa y Linconsa,"}]},{type:a,value:" de la extinta Secretaría de Desarrollo Social (Sedesol) para crear Segalmex, el cual "},{type:b,tag:e,props:{},children:[{type:a,value:"buscaba la autosuficiencia alimentaria en los cuatro granos básicos (maíz, trigo, arroz, frijol) y leche,"}]},{type:a,value:" fomentar el desarrollo económico y social del país, pero no tardó mucho en saltar a la polémica por presuntos actos de corrupción e irregularidades."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Era muy necesaria, sin embargo, esta institución se desvirtuó, se corrompió, fue el caso de corrupción más emblemático durante este sexenio”, señala Emiliano Montes de Oca, de Ethos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Los desvíos ocurrieron en 2019 y 2020 y, como en otros casos, mediante contratos sin licitación, empresas fantasma y factureras. Es decir, explica el experto, que se repitieron los esquemas en un Gobierno que apostó a combatir la corrupción con la buena voluntad y haciendo a un lado los sistemas anticorrupción existentes."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Aunque el gobierno interpuso 156 denuncias ante la Fiscalía General de la República (FGR) y en la cárcel hay exfuncionarios de Segalmex, quien fuera su director en la época de los desvíos, "},{type:b,tag:e,props:{},children:[{type:a,value:"Ignacio Ovalle, cercano a López Obrador, no enfrenta sanción alguna."}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Su exdirector Leonel Cota, quien se unió en 2022 a la dependencia cuando se investigaban ya los actos delictivos dejó su cargo este año para sumarse al equipo de la entonces candidata Claudia Sheinbaum. En agosto pasado se informó que se integraría a su Gabinete."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Recientemente Sheinbaum, ya como presidenta electa, anunció que en su sexenio se fusionarán Segalmex con Diconsa, a fin de retomar aquella "},{type:b,tag:"a",props:{href:"https:\u002F\u002Fpolitica.expansion.mx\u002Fpresidencia\u002F2024\u002F09\u002F17\u002Fclaudia-sheinbaum-fusionara-segalmex-diconsa?utm_source=internal&utm_medium=link-recommended",rel:["nofollow","noopener","noreferrer"],target:"_blank"},children:[{type:a,value:"promesa de mejorar la alimentación de los más vulnerables"}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Pero su reto será demostrar que sí implementa acciones anticorrupción y transparencia, porque la información del caso se reservó cinco años. “Es un cambio de nombre, es un cambio de marca, pero qué estás haciendo como Gobierno federal para prevenir que vuelva a ocurrir lo mismo”, afirma."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sheinbaum ha prometido una "},{type:b,tag:e,props:{},children:[{type:a,value:"Agencia Nacional Anticorrupción"}]},{type:a,value:", que pasará la prueba si sanciona a todos los implicados en el caso Segalmex."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"El fracaso del Insabi"}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El "},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:" comenzó sus operaciones en enero de 2020. Debía "},{type:b,tag:e,props:{},children:[{type:a,value:"otorgar fármacos y atención médica gratuitos a la población sin seguridad social"}]},{type:a,value:", pero registró varios fracasos. Estaba a cargo de la compra de medicamentos del sector salud y, sin experiencia, modificó el modelo de adquisición consolidada, lo que causó retrasos en las compras y distribución de los insumos, profundizando el desabasto de medicamentos en plena pandemia de covid-19."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A cargo de Julio Ferrer, un funcionario sin 'expertise' en salud, sino en la conservación del patrimonio histórico, el Insabi no funcionó mejor que el Seguro Popular, programa que sustituyó. Por el contrario, en los "},{type:b,tag:e,props:{},children:[{type:a,value:"primeros dos años de su operación, se incrementó la población sin acceso a servicios de salud"}]},{type:a,value:": de 20.1 en 2018 a 50.4 millones de personas en 2022."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Para Rodolfo de la Torre, el fracaso del Insabi se explica porque el Gobierno federal no aumentó el presupuesto destinado a la universalización de la atención médica, aunque planeaba incluir a miles de personas más, y a la aplicación de un modelo que centraliza los servicios de salud estatales."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Esto significó revertir el poco avance que se tenía anteriormente, con las consecuencias más adversas: "},{type:b,tag:e,props:{},children:[{type:a,value:"30 millones de personas perdiendo su acceso a los servicios de salud"}]},{type:a,value:"”, apunta."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En su momento, López Obrador argumentó que el incremento de gente sin acceso a salud era consecuencia de una pregunta mal planteada a la población sobre si tenía derecho al Seguro Popular o al Insabi."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sin embargo, otros indicadores dan cuenta del fracaso: en 2022 más personas se atendieron en servicios médicos privados y también gastaron más de dinero de su bolsillo en salud, explica Axel González, investigador de datos en México, ¿cómo vamos?"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Por los nulos resultados, el presidente decretó la extinción del Insabi en mayo de 2023 y creó el organismo público IMSS Bienestar, que antes operaba solo como un programa del IMSS en comunidades rurales. Ahora es el encargado de la atención de toda la población sin seguridad social."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A decir de los especialistas, IMSS Bienestar carga con algunos errores del pasado, como la centralización y la falta de aumento al presupuesto del sector, así que en el sexenio de Sheinbaum enfrentará retos para consolidarse, aumentar la cobertura y lograr que los mexicanos regresen a los hospitales públicos. “Esos resultados y su desaparición son un reflejo del fracaso que representó el Insabi ”, subraya el investigador González."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A unos meses de concluir su Gobierno, el mismo López Obrador tuvo que adminitir que el Insabi fue un “tropiezo administrativo” desde su puesta en marcha. “En el caso de la salud. Ahí no funcionó lo que teníamos pensado”, dijo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"Los \"Moches\" en el Indep"}]},{type:a,value:"\r\nEl Instituto para Devolver al Pueblo lo Robado (Indep) también ha sido señalado por ineficacia y acusaciones de \"amiguismo\" en su operación. Ha estado a cargo de perfiles que primero integraron la Ayudantía Presidencial, como su director Alberto Becerra, supuesto amigo de los hijos de López Obrador."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Y de funcionarios acusados de cobrar “moches” a los trabajadores. Así ocurrió con José Ángel Anzures, quien renunció a la Dirección Ejecutiva de Recursos Materiales tras revelarse que supuestamente les cobraba 30% del salario para que mantuvieran su puesto."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Un año después de su creación, el entonces titular Jaime Cárdenas renunció a su cargo y detalló supuestos actos de corrupción. \"Encontramos al inicio de nuestra función probables irregularidades administrativas, manipulación de subastas y robo de joyas\", aseguró."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A la fecha, el Indep tampoco ha logrado vender la totalidad de los bienes incautados a la delincuencia y ahora opera en bancarrota."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Lo paradójico es que, siendo una institución que le llegan activos, por una serie de adjudicaciones o extinciones de dominio, tenga números rojos, eso es un mal indicativo\", señala Rodolfo de la Torre, investigador del CEEY."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La incompetencia del Indep se relaciona, por ejemplo, con pagar jubilaciones a 125 trabajadores muertos, como detectó la ASF, olvidar predios incautados o subastar bienes antes de comprobar su procedencia ilícita."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La mala gestión gubernamental ve al instituto como un barril sin fondo: de él sale dinero para premiar a los atletas nacionales, pagar pensiones o construir hospitales."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Tanto los resultados del Indep, como los del Insabi y Segalmex, muestran que este sexenio operó con una Administración Pública de “porfirismo inverso”, como la denomina Rodolfo de la Torre, investigador del Centro de Estudios Espinosa Yglesias:"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Porfirio Díaz se jactaba de decir que en su Gobierno habría poca política y mucha administración, y aquí parece que ocurrió lo contrario: fue poca administración y mucha política. Eso significó el descuido, la negligencia, la incapacidad para atender asuntos de gestión pública”."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fcorrupcion_e_ineficacia_en_insabi_segalmex_e_indep_marcan_el_sexenio_de_amlo",extension:".md",createdAt:g,updatedAt:g}}],fetch:{},mutations:[]}}("text","element","p","\n","strong","Insabi","2024-10-02T22:32:44.087Z")));